cat > /tmp/rundd.cjs <<'PEOF'
const { readdirSync, readFileSync } = require('node:fs');
const { spawnSync } = require('node:child_process');
const d = '/workspace/probe/corpus/documents-directives/';
const files = readdirSync(d).sort();
const rc = {};
const argparseErrs = [];
for (const f of files) {
  const s = readFileSync(d + f, 'utf8');
  const r = spawnSync('/workspace/dataset/test14_executable', ['--a', s], { encoding: 'utf8' });
  rc[r.status] = (rc[r.status] || 0) + 1;
  if (r.status === 2) argparseErrs.push(f);
  if (['001.txt','008.txt','010.txt','041.txt','062.txt','066.txt','102.txt','122.txt','128.txt','134.txt'].includes(f)) {
    console.log('=== ' + f + ' in=' + JSON.stringify(s) + ' rc=' + r.status);
    const out = (r.stdout || '') + (r.stderr || '');
    console.log('    out=' + JSON.stringify(out.split('\n').slice(0, 4).join('\n')));
  }
}
console.log('rc distribution:', JSON.stringify(rc));
console.log('argparse(rc=2) cases:', argparseErrs.length ? argparseErrs.join(',') : 'none');
